// Repro for bucket A (data_order): the eight data bits must be sent least
// significant first. Checks only the data field; parity and stop timing are
// not observed.
`timescale 1ns / 1ps
module uart_frame_tx_repro_tb;
    localparam integer C = 4;               // CLKS_PER_BIT

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer    checks = 0;
    integer    failed = 0;
    reg        verdict_done = 1'b0;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(C)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task report_verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d %0s",
                         nonce, checks, failed, (failed != 0) ? "FAIL" : "PASS");
            end
        end
    endtask

    task send_and_check;
        input [7:0] d;
        integer k;
        integer w;
        reg [7:0] got;
        begin
            @(negedge clk); data = d; start = 1'b1;
            @(negedge clk); start = 1'b0;          // N0: just after the edge that took start
            repeat (C/2) @(negedge clk);           // centre of the start bit
            for (k = 0; k < 8; k = k + 1) begin
                repeat (C) @(negedge clk);         // centre of data bit k
                got[k] = tx;
            end
            checks = checks + 1;
            if (got !== d) begin
                failed = failed + 1;
                $display("CHECK data_order FAIL sent=%02h received_lsb_first=%02h", d, got);
            end else
                $display("CHECK data_order PASS sent=%02h", d);
            w = 0;
            while (busy !== 1'b0 && w < 200) begin
                @(negedge clk);
                w = w + 1;
            end
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nonce=%s", nonce)) nonce = "unset";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send_and_check(8'hA3);
        send_and_check(8'h01);
        send_and_check(8'h5C);
        report_verdict;
        $finish;
    end

    initial begin
        #100000;
        $display("CHECK watchdog FAIL simulation did not complete");
        checks = checks + 1;
        failed = failed + 1;
        report_verdict;
        $finish;
    end
endmodule
=== END FILE ===
