    localparam integer C = 4;               // CLKS_PER_BIT

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer    checks = 0;
    integer    failed = 0;
    reg        verdict_done = 1'b0;
    reg [8*128-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(C)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task get_nonce;
        begin
            if      ($value$plusargs("nonce=%s", nonce))         ;
            else if ($value$plusargs("NONCE=%s", nonce))         ;
            else if ($value$plusargs("verdict_nonce=%s", nonce)) ;
            else if ($value$plusargs("VERDICT_NONCE=%s", nonce)) ;
            else if ($value$plusargs("run_nonce=%s", nonce))     ;
            else if ($value$plusargs("RUN_NONCE=%s", nonce))     ;
            else nonce = "unset";
        end
    endtask

    task report_verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d %0s",
                         nonce, checks, failed, (failed != 0) ? "FAIL" : "PASS");
            end
        end
    endtask

    task send_and_measure;
        input [7:0] d;
        integer n;
        begin
            @(negedge clk); data = d; start = 1'b1;
            @(negedge clk); start = 1'b0;          // N0: busy should already be high
            n = 0;
            while (busy === 1'b1 && n < 500) begin
                n = n + 1;
                @(negedge clk);
            end
            checks = checks + 1;
            if (n != 11*C) begin
                failed = failed + 1;
                $display("CHECK frame_period FAIL data=%02h busy_cycles=%0d expected=%0d", d, n, 11*C);
            end else
                $display("CHECK frame_period PASS data=%02h busy_cycles=%0d", d, n);
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        get_nonce;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send_and_measure(8'h55);
        send_and_measure(8'h00);
        report_verdict;
        $finish;
    end

    initial begin
        #100000;
        $display("CHECK watchdog FAIL simulation did not complete");
        checks = checks + 1;
        failed = failed + 1;
        report_verdict;
        $finish;
    end
endmodule
